const store = $getWorkflowStaticData('global');
const q = $json.query || {};
let text = '';
if (q.id && store.notes && store.notes[q.id]) {
  text = store.notes[q.id].text;
} else if (q.d) {
  try { text = Buffer.from(String(q.d).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8'); } catch (e) {}
}
const lines = String(text).split('\n');
const title = lines[0] || '';
const content = lines.slice(1).join('\n').replace(/^\n+/, '');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const jsFull = JSON.stringify(text || '');
const hasText = String(text).trim().length > 0;
const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Ma liste — I-Interim</title>
<style>
:root{--accent:#7B2CBF;--accent2:#9D4EDD;--bg:#F3F0FA;--card:#fff;--text:#1E1B29;--muted:#6B6780;}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
body{margin:0;min-height:100vh;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;padding:20px;padding-bottom:calc(20px + env(safe-area-inset-bottom));}
.wrap{max-width:640px;margin:0 auto;}
header{display:flex;align-items:center;gap:12px;margin-bottom:18px;}
.mark{width:40px;height:40px;border-radius:12px;flex-shrink:0;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;}
h1{font-size:1.15rem;margin:0;}
.card{background:var(--card);border-radius:20px;padding:20px;box-shadow:0 12px 30px rgba(72,26,122,.10);}
.note-title{font-size:1.25rem;font-weight:800;color:var(--accent);margin:0 0 12px;}
pre{white-space:pre-wrap;word-wrap:break-word;font-family:inherit;font-size:1.02rem;line-height:1.6;margin:0;}
.actions{position:sticky;bottom:0;display:flex;gap:10px;margin-top:18px;padding:12px 0 4px;}
button{flex:1;font-family:inherit;font-size:1.05rem;font-weight:700;border:none;border-radius:16px;padding:16px;cursor:pointer;}
#share{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;box-shadow:0 10px 24px rgba(123,44,191,.3);}
#copy{background:#fff;color:var(--muted);border:2px solid rgba(123,44,191,.18);}
button:active{transform:scale(.97);}
.toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);background:var(--text);color:#fff;padding:12px 20px;border-radius:999px;font-size:.95rem;opacity:0;transition:opacity .25s;pointer-events:none;}
.toast.show{opacity:1;}
.empty{color:var(--muted);text-align:center;padding:40px 0;}
</style></head><body><div class="wrap">
<header><div class="mark">G1</div><h1>Robot I-Interim</h1></header>
<div class="card">${hasText ? `<div class="note-title">${esc(title)}</div><pre>${esc(content)}</pre>` : `<div class="empty">Aucun contenu à afficher.</div>`}</div>
${hasText ? `<div class="actions"><button id="share">📝 Enregistrer dans mes notes</button><button id="copy">📋 Copier</button></div>` : ``}
</div><div class="toast" id="toast"></div>
<script>
const fullText = ${jsFull};
function toast(m){const t=document.getElementById('toast');if(!t)return;t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800);}
async function copyText(){try{await navigator.clipboard.writeText(fullText);}catch(e){const ta=document.createElement('textarea');ta.value=fullText;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);}}
const sb=document.getElementById('share');
if(sb){sb.addEventListener('click',async()=>{if(navigator.share){try{await navigator.share({title:document.title,text:fullText});}catch(e){}}else{await copyText();toast('Copié — collez dans vos notes');}});}
const cb=document.getElementById('copy');
if(cb){cb.addEventListener('click',async()=>{await copyText();toast('Copié ✔');});}
</script></body></html>`;
return [{ json: { html } }];

const store = $getWorkflowStaticData('global');
if (!store.notes) store.notes = {};
const now = Date.now();
// nettoyage : on jette les notes de plus de 24h (le store ne gonfle pas)
for (const k of Object.keys(store.notes)) {
  if (now - (store.notes[k].ts || 0) > 86400000) delete store.notes[k];
}
const body = $json.body || $json;
const text = String(body.text || '');
let id;
do { id = Math.random().toString(36).slice(2, 8); } while (store.notes[id]);
store.notes[id] = { text, ts: now };
return [{ json: { id, url: 'https://n8n.i-interim.com/webhook/note?id=' + id } }];
